<h1><?= te('Client requests') ?></h1><p class="sub"><?= te('Record email, phone or meeting instructions. Client login is optional; approved requests become projects.') ?></p>
<form method="post" class="card"><?= csrf_field() ?><input type="hidden" name="do" value="create"><h2><?= te('Record a client request') ?></h2><div class="grid g3"><div><label><?= te('Client') ?></label><select name="client_id" required><?php foreach($clients as $client): ?><option value="<?= (int)$client['id'] ?>"><?= e($client['name']) ?></option><?php endforeach; ?></select></div><div><label><?= te('Request title') ?></label><input name="title" required maxlength="190"></div><div><label><?= te('Workers requested') ?></label><input name="headcount" type="number" min="1" max="100000" required></div><div><label><?= te('Source') ?></label><select name="source"><?php foreach(['email','phone','meeting','other'] as $source): ?><option value="<?= e($source) ?>"><?= te($source) ?></option><?php endforeach; ?></select></div><div><label><?= te('Source reference') ?></label><input name="source_reference" maxlength="190"></div><div><label><?= te('Client contact') ?></label><input name="requested_by" maxlength="190"></div><div><label><?= te('City') ?></label><input name="site_city" maxlength="120"></div><div><label><?= te('State') ?></label><input name="site_state" maxlength="40"></div><div><label><?= te('Start date') ?></label><input name="starts_on" type="date"><label><?= te('End date') ?></label><input name="ends_on" type="date"></div></div><label><?= te('Requirements and client instructions') ?></label><textarea name="description" required maxlength="10000"></textarea><button class="btn"><?= te('Save request') ?></button></form>
<?php foreach($orders as $order): ?><section class="card"><span class="tag"><?= te($order['status']) ?></span><h2><?= e($order['title'].' · '.$order['client_name']) ?></h2><p><?= e($order['description']) ?></p><p class="muted"><?= e($order['headcount'].' · '.$order['site_city'].' · '.$order['site_state'].' · ') ?><?= te($order['source']) ?> · <?= e($order['source_reference']) ?></p><?php if($order['status']!=='converted'): ?><form class="row" method="post"><?= csrf_field() ?><input type="hidden" name="do" value="update"><input type="hidden" name="order_id" value="<?= (int)$order['id'] ?>"><select name="status"><?php foreach(['new','reviewing','approved','declined'] as $status): ?><option value="<?= e($status) ?>" <?= $order['status']===$status?'selected':'' ?>><?= te($status) ?></option><?php endforeach; ?></select><input name="note" required maxlength="10000" placeholder="<?= te('Update instructions / decision note') ?>"><label><?= te('Workers requested') ?></label><input name="headcount" type="number" min="1" max="100000" required value="<?= (int)$order['headcount'] ?>"><label><?= te('Requirements and client instructions') ?></label><textarea name="description" maxlength="10000" required><?= e($order['description']) ?></textarea><button class="btn ghost"><?= te('Update request') ?></button></form><?php if($order['status']==='approved'): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="do" value="convert"><input type="hidden" name="order_id" value="<?= (int)$order['id'] ?>"><button class="btn"><?= te('Create project from request') ?></button></form><?php endif; ?><?php else: ?><form method="post" action="/select-project"><?= csrf_field() ?><input type="hidden" name="job_id" value="<?= (int)$order['job_id'] ?>"><button class="btn"><?= te('Open project') ?></button></form><p><?= te('Configure project terms, then create its application QR in Requisitions.') ?></p><?php endif; ?><details><summary><?= te('Request history') ?></summary><?php foreach($events as $event):if((int)$event['order_id']!==(int)$order['id'])continue; ?><p><?= e($event['created_at'].' · '.$event['name'].' · ') ?><?= te($event['action']) ?> · <?= e($event['note']) ?></p><?php endforeach; ?></details></section><?php endforeach; ?>

<?= page_controls($page,count($orders)) ?>
